#include "pch.h"
#include "PrintService.h"
#include "DocumentRenderer.h"
#include "../core/ImageOperations.h"
namespace sct::services {
core::Image PrintPagePreview(const core::DocumentState& state,CString& error){core::Image rendered;if(!RenderDocument(state,rendered,error))return {};const bool landscape=rendered.width>rendered.height;int pw=landscape?842:595,ph=landscape?595:842;double scale=std::min((pw-48.0)/rendered.width,(ph-48.0)/rendered.height);auto scaled=core::Flatten(core::Resize(rendered,std::max(1,static_cast<int>(rendered.width*scale)),std::max(1,static_cast<int>(rendered.height*scale))));int left=(pw-scaled.width)/2,top=(ph-scaled.height)/2;return core::Canvas(scaled,left,top,pw-scaled.width-left,ph-scaled.height-top,RGB(255,255,255));}
bool PrintDocument(const core::DocumentState& state,const PrinterSettings& printer,CString& error){core::Image rendered;if(!RenderDocument(state,rendered,error))return false;auto image=core::Flatten(rendered);auto mode=printer.mode;DEVMODE* settings=nullptr;if(!mode.empty()){if(mode.size()<sizeof(DEVMODE)){error=L"Invalid printer settings";return false;}settings=reinterpret_cast<DEVMODE*>(mode.data());if(settings->dmSize>mode.size()||settings->dmDriverExtra>mode.size()-settings->dmSize){error=L"Invalid printer mode length";return false;}settings->dmCopies=1;settings->dmFields|=DM_COPIES;}HDC dc=CreateDC(printer.driver,printer.device,printer.port,settings);if(!dc){error.Format(L"Create printer DC failed (Win32=%lu)",GetLastError());return false;}DOCINFO info{sizeof(info)};info.lpszDocName=L"Simple Capture Tool";info.lpszOutput=printer.output.IsEmpty()?nullptr:printer.output.GetString();bool started=StartDoc(dc,&info)>0,ok=started;int pw=GetDeviceCaps(dc,HORZRES),ph=GetDeviceCaps(dc,VERTRES),dx=std::max(1,GetDeviceCaps(dc,LOGPIXELSX)),dy=std::max(1,GetDeviceCaps(dc,LOGPIXELSY));int marginX=std::max(0,dx/3),marginY=std::max(0,dy/3);double scale=std::min(static_cast<double>(std::max(1,pw-marginX*2))/(static_cast<double>(image.width)*dx),static_cast<double>(std::max(1,ph-marginY*2))/(static_cast<double>(image.height)*dy));int w=std::max(1,static_cast<int>(image.width*dx*scale)),h=std::max(1,static_cast<int>(image.height*dy*scale));BITMAPINFO bitmap{};bitmap.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bitmap.bmiHeader.biWidth=image.width;bitmap.bmiHeader.biHeight=-image.height;bitmap.bmiHeader.biPlanes=1;bitmap.bmiHeader.biBitCount=32;
    for(int copy=0;copy<std::clamp(printer.copies,1,99)&&ok;++copy){ok=StartPage(dc)>0;if(ok){SetStretchBltMode(dc,HALFTONE);SetBrushOrgEx(dc,0,0,nullptr);ok=StretchDIBits(dc,(pw-w)/2,(ph-h)/2,w,h,0,0,image.width,image.height,image.pixels.data(),&bitmap,DIB_RGB_COLORS,SRCCOPY)!=GDI_ERROR;}if(ok)ok=EndPage(dc)>0;}if(ok)ok=EndDoc(dc)>0;else if(started)AbortDoc(dc);DeleteDC(dc);if(!ok)error.Format(L"Printing failed (Win32=%lu)",GetLastError());return ok;}
}
